// Trocea el documento en fragmentos con apartado y posicion.
// Ajusta TAMANO y SOLAPE segun la regla que decidiste con el prompt de troceado.
const TAMANO = 1400;
const SOLAPE = 200;
const doc = $input.first().json;
if (!doc.id_documento) throw new Error('Stable document id is required for replacement and replay');
const texto = doc.texto || '';

// Corte primero por apartados si vienen marcados con lineas '## '
const bloques = [];
const partes = texto.split(/\n(?=## )/);
for (const parte of partes) {
  const lineas = parte.split('\n');
  const primera = lineas[0] || '';
  const esTitulo = primera.startsWith('## ');
  const apartado = esTitulo ? primera.replace(/^## /, '').trim() : 'sin apartado';
  const cuerpo = (esTitulo ? lineas.slice(1).join('\n') : parte).trim();
  if (cuerpo.length > 0) bloques.push({ apartado, cuerpo });
}
if (bloques.length === 0) bloques.push({ apartado: 'sin apartado', cuerpo: texto });

// Dentro de cada apartado, corte por longitud con solape
const salida = [];
let posicion = 0;
for (const bloque of bloques) {
  let inicio = 0;
  while (inicio < bloque.cuerpo.length) {
    const trozo = bloque.cuerpo.slice(inicio, inicio + TAMANO);
    posicion += 1;
    salida.push({
      json: {
        id_documento: doc.id_documento,
        titulo: doc.titulo,
        coleccion: doc.coleccion,
        dueno: doc.dueno,
        version: doc.version,
        apartado: bloque.apartado,
        posicion: posicion,
        texto: doc.titulo + ' > ' + bloque.apartado + ': ' + trozo.trim(),
      },
    });
    if (inicio + TAMANO >= bloque.cuerpo.length) break;
    inicio += TAMANO - SOLAPE;
  }
}
if (salida.length > 100) throw new Error('Document too long: split it before ingestion');
return [{json:{...doc,fragmentos:salida.map(i=>i.json)} }];

// Junta todos los fragmentos en un solo item para llamar una vez al modelo.
const items = $input.all();
const primero = items[0].json;
const muestra = items.slice(0, 8).map((i) => i.json.texto).join('\n---\n');
return [{
  json: {
    id_documento: primero.id_documento,
    titulo: primero.titulo,
    coleccion: primero.coleccion,
    dueno: primero.dueno,
    version: primero.version,
    total_fragmentos: items.length,
    muestra: muestra.slice(0, 6000),
  },
}];

